    private static let psychology = DirectorySource(name: "Gesundheitsportal · Klinische Psychologie", url: "https://www.gesundheit.gv.at/gesundheitsleistungen/berufe/gesundheitsberufe-a-z/psychologische-berufe/klinische-psychologie.html")
